{
  "missing_information": [
    {
      "category": "Message Sources",
      "gap": "It is unclear which channels or platforms childcare uses to send notices (e.g., email, SMS, a dedicated app, paper notes)",
      "why_it_matters": "Automation depends on being able to programmatically access and parse incoming messages; different channels require different integration approaches"
    },
    {
      "category": "Response Triggers",
      "gap": "There is no definition of what criteria determine whether a message requires a response versus simply being read and acknowledged",
      "why_it_matters": "Without clear rules for when a reply is needed, it is impossible to automate triage or draft responses accurately"
    },
    {
      "category": "Reminder Storage",
      "gap": "It is not specified where or how special events and items-to-bring are recorded (e.g., a calendar, a to-do list app, a shared family note)",
      "why_it_matters": "The target system for reminders must be known to automate the capture and scheduling of follow-up actions"
    },
    {
      "category": "Message Classification",
      "gap": "There is no taxonomy of message types (e.g., permission slips, schedule changes, health alerts, fundraising requests) and how each is handled differently",
      "why_it_matters": "Classifying messages is a prerequisite for routing them to the correct automated action or human decision"
    },
    {
      "category": "Response Authoring",
      "gap": "It is unclear whether responses are free-form, chosen from fixed options, or require attaching documents or signatures",
      "why_it_matters": "The complexity of response authoring determines whether automation can generate replies or only draft them for human approval"
    },
    {
      "category": "Deadline Handling",
      "gap": "There is no information about how response deadlines or RSVP cut-off dates are identified and tracked",
      "why_it_matters": "Deadline awareness is critical for prioritising messages and triggering timely reminders before opportunities or compliance windows close"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "Through which channel or platform does childcare send notices to you — for example, a dedicated parent app, email, SMS, or physical handouts — and is there a single channel or multiple?",
      "targets": ["Message Sources"]
    },
    {
      "id": "Q2",
      "question": "What makes you decide that a particular message needs a reply rather than just being read — is there a specific keyword, a question being asked, or a request for confirmation?",
      "targets": ["Response Triggers"]
    },
    {
      "id": "Q3",
      "question": "When you note a special event or item to bring, where exactly do you record it — for instance, a phone calendar, a shared family app, or a physical list?",
      "targets": ["Reminder Storage"]
    },
    {
      "id": "Q4",
      "question": "Can you describe the main types of messages you receive from childcare and whether each type is handled differently — for example, permission slips versus health alerts versus schedule changes?",
      "targets": ["Message Classification"]
    },
    {
      "id": "Q5",
      "question": "When you do need to respond, is your reply typically a free-text message, a selection from fixed options provided by childcare, or does it sometimes require attaching a signed form or document?",
      "targets": ["Response Authoring"]
    },
    {
      "id": "Q6",
      "question": "How do you currently track response deadlines or RSVP cut-off dates — are they stated in the message itself, and do you set any reminders to ensure you reply in time?",
      "targets": ["Deadline Handling"]
    }
  ]
}
